window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c22397f7d770b2ba"]={"versions": [{"id": "FIG-c22397f7d770b2ba", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Bitfeldspezifikation (Wire-Format-Diagramm) für das Service-Discovery-Protokoll SOME/IP-SD innerhalb des AUTOSAR-Kommunikationsstacks. Das Diagramm spezifiziert das binäre Layout der IPv6 Endpoint Option als Bestandteil des Options-Arrays in SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Binäres Options-Format mit einer Bitbreite von 32 Bit pro Zeile:</p>\n<ul class=\"fig-list\"><li><code>Length (=0x0015)</code>: 16 Bit (Bit 0–15), deklariert die abgedeckte Restlänge von 21 Byte (0x15).\n</li><li><code>Type (=0x06)</code>: 8 Bit (Bit 16–23), Typschlüssel der IPv6 Endpoint Option.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 24–31), reserviertes Feld im Options-Header.\n</li><li><code>IPv6-Address [128bit]</code>: 128 Bit (Bit 0–31 über 4 Zeilen), IPv6-Netzwerkadresse.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 0–7), reserviertes Feld.\n</li><li><code>L4-Proto (TCP/UDP...)</code>: 8 Bit (Bit 8–15), Kennung des Layer-4-Transportprotokolls (z. B. TCP=0x06, UDP=0x11).\n</li><li><code>Port Number</code>: 16 Bit (Bit 16–31), Transport-Portnummer.\n</li></ul>\n<p class=\"fig-p\">Eine seitliche Bemaßung (<code>Covered by Length (incl. Reserved)</code>) markiert den Datenbereich ab Byte 3 (Bit 24 der ersten Zeile) bis zum Ende der Option über exakt 21 Byte.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Option wird im Options-Array einer SOME/IP-SD-Nachricht transportiert und durch Entry-Blöcke (z. B. Offer Service oder Subscribe Eventgroup) referenziert. Die Serialisierung und Deserialisierung erfolgt netzwerkweit in Big-Endian-Bytereihenfolge (Network Byte Order). Beim Deserialisieren validiert der Empfänger das Feld <code>Length</code> (21 Byte) sowie <code>Type</code> (0x06), liest die 128-Bit-IPv6-Adresse und assoziiert die angegebene L4-Protokoll- und Port-Kombination mit der jeweiligen Service- bzw. Eventgruppen-Instanz.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Wire-Format für SOME/IP-SD-Endpoints über IPv6. Entwickler müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li><code>Length</code> fest auf <code>0x0015</code> (21 dezimal) gesetzt wird und die nachfolgenden 21 Bytes einschließlich des ersten reservierten Bytes umfasst.\n</li><li><code>Type</code> den Wert <code>0x06</code> führt.\n</li><li>Reservierte Felder (<code>Reserved</code>) mit <code>0x00</code> initialisiert und beim Empfang ignoriert werden.\n</li><li>Die Felder <code>IPv6-Address</code>, <code>L4-Proto</code> und <code>Port Number</code> konsistent zu den AUTOSAR-Netzwerkkonfigurationen (<code>SoAd</code>, <code>TcpIp</code>) bedient werden.\n</li></ul>"}, {"id": "FIG-78847baebbf9cd75", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Bitfeldspezifikation (Wire-Format-Diagramm) für das Service-Discovery-Protokoll SOME/IP-SD innerhalb des AUTOSAR-Kommunikationsstacks. Das Diagramm spezifiziert das binäre Layout der IPv6 SD Endpoint Option (option-id = 0x26) als Bestandteil des Options-Arrays in SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Binäres Options-Format mit einer Bitbreite von 32 Bit pro Zeile und Diagrammtitel <code>Option format: IPv6 SD Endpoint Option (option-id = 0x26)</code>:</p>\n<ul class=\"fig-list\"><li><code>Length (=0x0015)</code>: 16 Bit (Bit 0–15), deklariert die abgedeckte Restlänge von 21 Byte (0x15).\n</li><li><code>Type (=0x26)</code>: 8 Bit (Bit 16–23), Optionskennung für IPv6 SD Endpoint Option.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 24–31), reserviertes Feld im Options-Header.\n</li><li><code>IPv6-Address [128bit]</code>: 128 Bit (Bit 0–31 über 4 Zeilen), IPv6-Netzwerkadresse.\n</li><li><code>Reserved (=0x00)</code>: 8 Bit (Bit 0–7), reserviertes Feld.\n</li><li><code>L4-Proto (UDP/...)</code>: 8 Bit (Bit 8–15), Kennung des Layer-4-Transportprotokolls.\n</li><li><code>Port Number</code>: 16 Bit (Bit 16–31), Transport-Portnummer.\n</li></ul>\n<p class=\"fig-p\">Eine seitliche Bemaßung (<code>Covered by Length (incl. Reserved)</code>) markiert den Datenbereich ab Bit 24 der ersten Zeile bis zum Ende der Option über exakt 21 Byte.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Option wird im Options-Array einer SOME/IP-SD-Nachricht übertragen und von Service- oder Eventgroup-Entries referenziert. Die Übertragung erfolgt in Big-Endian-Bytereihenfolge. Empfänger prüfen den Typwert <code>0x26</code> und die Länge <code>0x0015</code>, extrahieren die 128-Bit-IPv6-Adresse sowie L4-Protokollkennung und Portnummer zur Adressierung von SD-Endpunkten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Wire-Format für SOME/IP-SD IPv6-Endpunkte. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li><code>Type</code> ist auf <code>0x26</code> (Option-ID für IPv6 SD Endpoint Option) festgelegt.\n</li><li><code>Length</code> beträgt <code>0x0015</code> (21 Byte) und deckt das erste reservierte Byte, die IPv6-Adresse, das nachfolgende reservierte Byte, das L4-Protokoll und die Portnummer ab.\n</li><li>Sämtliche <code>Reserved</code>-Felder müssen mit <code>0x00</code> gesendet werden.\n</li><li>Die Port- und Adressangaben müssen der IPv6-Transportkonfiguration des Endpunkts entsprechen.\n</li></ul>"}], "trans": []};
